package com.mushafi.app;
import android.app.*;import android.content.*;import android.media.*;import android.webkit.*;import java.io.*;import java.net.*;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.*;import org.json.*;
/** Pinned real verse clips and native playback. No account, guessed cuts or emulator endpoints. */
public final class InlineReaderChecks {
 interface Check{boolean get()throws Exception;}
 static void until(Check check)throws Exception{long end=System.currentTimeMillis()+60000;while(System.currentTimeMillis()<end){if(check.get())return;Thread.sleep(100);}throw new Exception("Inline playback timeout");}
 static void need(boolean yes,String why)throws Exception{if(!yes)throw new Exception(why);}
 static Object field(Object value,String name)throws Exception{Field f=value.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(value);}
 static byte[] asset(Instrumentation test,String name)throws Exception{try(InputStream in=test.getContext().getAssets().open("inline63/"+name);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toByteArray();}}
 static class Capture extends WebView {final List<JSONObject> events=new CopyOnWriteArrayList<>();Capture(Context c){super(c);}@Override public void evaluateJavascript(String script,ValueCallback<String> result){try{String marker="window.onNativeAudio(";int at=script.indexOf(marker);if(at>=0)events.add(new JSONObject(script.substring(at+marker.length(),script.length()-1)));}catch(Exception e){throw new IllegalStateException(e);}if(result!=null)result.onReceiveValue("null");}long count(String status){long n=0;for(JSONObject e:events)if(status.equals(e.optString("status")))n++;return n;}}
 static URL simulated(byte[] bytes,long base,long total,int mode)throws Exception{return new URL(null,"https://download.qurancomplex.gov.sa/new-sounds/fixture.zip",new URLStreamHandler(){protected URLConnection openConnection(URL url){return new HttpURLConnection(url){long start,end;byte[] body;public void connect(){}public void disconnect(){}public boolean usingProxy(){return false;}void prepare(){String[] parts=getRequestProperty("Range").substring(6).split("-");start=Long.parseLong(parts[0]);end=Math.min(Long.parseLong(parts[1]),start+7776);int offset=(int)(start-base);body=Arrays.copyOfRange(bytes,offset,offset+(int)(end-start+1));}public int getResponseCode(){prepare();return mode==1?200:206;}public String getHeaderField(String name){return "Content-Range".equals(name)?"bytes "+(mode==2?start+1:start)+"-"+end+"/"+total:null;}public InputStream getInputStream(){return new ByteArrayInputStream(body);}};}});}
 public static void run(Instrumentation test)throws Exception{Context c=test.getTargetContext();JSONObject fixtures=new JSONObject(new String(asset(test,"manifest.json"),"UTF-8"));LaunchHarnessActivity a=(LaunchHarnessActivity)test.startActivitySync(new Intent(c,LaunchHarnessActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Capture[] web=new Capture[1];test.runOnMainSync(()->web[0]=new Capture(a));AudioEngine engine=new AudioEngine(a,web[0]);ArrayList<File> created=new ArrayList<>();
 try{
 for(String name:new String[]{"1002_1_1","1003_1_1","1004_1_1","1003_9_127"}){JSONObject proof=fixtures.getJSONObject(name);JSONArray entry=proof.getJSONArray("entry");byte[] raw=asset(test,name+".entry"),expected=asset(test,name+".mp3");long base=entry.getLong(0);PublisherVerseArchive.Range reader=(start,length)->{int offset=(int)(start-base);if(offset<0||offset+length>raw.length)throw new IOException("Range outside fixture");return Arrays.copyOfRange(raw,offset,offset+length);};need(Arrays.equals(PublisherVerseArchive.extract(entry,reader,()->false),expected),"Publisher extraction gives exact verse "+name);URL rangeURL=simulated(raw,base,proof.getLong("archiveSize"),0);byte[] throughRanges=PublisherVerseArchive.extract(entry,(start,length)->PublisherVerseArchive.range(rangeURL,proof.getLong("archiveSize"),start,length,()->false,connection->{}),()->false);need(Arrays.equals(throughRanges,expected),"Bounded partial HTTP ranges reconstruct verse "+name);
 for(int bad:new int[]{1,2}){boolean rejected=false;try{PublisherVerseArchive.range(simulated(raw,base,proof.getLong("archiveSize"),bad),proof.getLong("archiveSize"),base,30,()->false,connection->{});}catch(Exception e){rejected=true;}need(rejected,"HTTP 200/incorrect Content-Range rejected");}
 byte[] corrupt=raw.clone();corrupt[corrupt.length-15]^=3;boolean rejected=false;try{PublisherVerseArchive.extract(entry,(start,length)->Arrays.copyOfRange(corrupt,(int)(start-base),(int)(start-base)+length),()->false);}catch(Exception e){rejected=true;}need(rejected,"Corrupted recording rejected");boolean cancelled=false;try{PublisherVerseArchive.extract(entry,reader,()->true);}catch(InterruptedIOException e){cancelled=true;}need(cancelled,"Cancelled extraction cannot commit audio");
 }
 // Production host validation is independent from the injected byte-range fixture.
 boolean blocked=false;try{PublisherVerseArchive.checked("https://example.com/fixture.zip");}catch(Exception e){blocked=true;}need(blocked,"Untrusted archive host rejected");
 for(int id:new int[]{3,1001,1002,1003,1004}){byte[] data=asset(test,id+"_1_1.mp3");Method path=AudioEngine.class.getDeclaredMethod("file",int.class,String.class);path.setAccessible(true);File target=(File)path.invoke(engine,id,"1:1");target.getParentFile().mkdirs();if(!target.exists())created.add(target);try(FileOutputStream out=new FileOutputStream(target)){out.write(data);}need(engine.has(id,"1:1"),"New reciter cache recognized "+id);test.runOnMainSync(()->engine.play(id,"1:1"));until(()->field(engine,"player")!=null&&((MediaPlayer)field(engine,"player")).isPlaying());MediaPlayer player=(MediaPlayer)field(engine,"player");need(player.getDuration()>500,"Real individual MP3 plays "+id);test.runOnMainSync(engine::pause);need(!player.isPlaying(),"Pause preserves selected verse "+id);test.runOnMainSync(engine::resume);until(player::isPlaying);test.runOnMainSync(engine::stop);need(field(engine,"player")==null,"Stop releases only the verse player "+id);}
 // Natural completion three times; no transition to another verse or reader.
 long before=web[0].count("ended");for(int repeat=0;repeat<3;repeat++){final int n=repeat;test.runOnMainSync(()->engine.play(3,"1:1"));until(()->web[0].count("ended")==before+n+1);}need(web[0].count("ended")==before+3,"Exactly three native completions");
 File sample=new File(c.getFilesDir(),"inline-late.mp3");created.add(sample);try(FileOutputStream out=new FileOutputStream(sample)){out.write(asset(test,"1003_9_127.mp3"));}Method ready=AudioEngine.class.getDeclaredMethod("archiveReady",long.class,int.class,String.class,File.class,Exception.class);ready.setAccessible(true);test.runOnMainSync(()->{try{engine.play(1003,"9:127");long old=(Long)field(engine,"generation");engine.stop();ready.invoke(engine,old,1003,"9:127",sample,null);need(field(engine,"player")==null,"Closing during load prevents late playback");engine.play(3,"1:1");Object current=field(engine,"player");ready.invoke(engine,old,1003,"9:127",sample,null);need(field(engine,"player")==current,"Stale completed fetch cannot replace newly selected reciter");engine.stop();}catch(Exception e){throw new RuntimeException(e);}});
 need(!engine.has(999,"1:1")&&!engine.has(1003,"../1"),"Unknown reader/path cannot access cache");test.runOnMainSync(()->{engine.destroy();engine.play(1003,"9:127");engine.download(1003,1,7);});need(field(engine,"player")==null,"Late bridge work after destruction cannot play or submit to closed executors");
 }finally{test.runOnMainSync(()->{engine.destroy();web[0].destroy();a.finish();});for(File f:created)f.delete();}
 }
}
